def _validate_label(text: str) -> None:
    # The panel reserves 24 bytes per label; a multibyte character consumes
    # more than one of those bytes, so counting characters would exceed its slot.
    if len(text.encode("utf-8")) > 24:
        raise ValueError("label exceeds panel storage")

