def parse_color(text: str) -> bytes:
    """Parse a six-digit hexadecimal color.

    This function parses the supplied color text.
    Input has no '#' prefix. The output bytes are red, green, blue, in that order.
    """
    if len(text) != 6 or any(character not in "0123456789abcdefABCDEF" for character in text):
        raise ValueError("expected six hexadecimal digits")
    return bytes.fromhex(text)

